CREATE SCHEMA IF NOT EXISTS maize_q9; SET search_path TO maize_q9,public;
CREATE TABLE IF NOT EXISTS farmers(farmer_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,farmer_number TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deliveries(delivery_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,farmer_id INT NOT NULL REFERENCES farmers,grade CHAR(1) NOT NULL CHECK(grade IN('A','B','C')),weight_kg NUMERIC(12,2) NOT NULL CHECK(weight_kg>0),unit_rate NUMERIC(8,2) NOT NULL DEFAULT 0,total_value NUMERIC(14,2) NOT NULL DEFAULT 0,delivered_on DATE NOT NULL,is_paid BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS daily_purchases(purchase_date DATE PRIMARY KEY,total_weight NUMERIC(14,2) NOT NULL,total_value NUMERIC(14,2) NOT NULL);
INSERT INTO farmers VALUES(1,'F001','Farmer One'),(2,'F002','Farmer Two'),(3,'F003','Farmer Three') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION fn_maize_rate(p_grade CHAR(1)) RETURNS NUMERIC(8,2) LANGUAGE plpgsql AS $$
BEGIN IF p_grade IS NULL THEN RAISE EXCEPTION 'Grade required'; END IF; CASE upper(p_grade) WHEN 'A' THEN RETURN 5; WHEN 'B' THEN RETURN 4; WHEN 'C' THEN RETURN 3; ELSE RAISE EXCEPTION 'Unsupported grade %',p_grade; END CASE; END $$;
CREATE OR REPLACE FUNCTION fn_price_delivery() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.weight_kg IS NULL OR NEW.weight_kg<=0 THEN RAISE EXCEPTION 'Weight must be positive'; END IF; NEW.unit_rate:=fn_maize_rate(NEW.grade); NEW.total_value:=NEW.weight_kg*NEW.unit_rate; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_price_delivery ON deliveries;
CREATE TRIGGER trg_price_delivery BEFORE INSERT OR UPDATE ON deliveries FOR EACH ROW EXECUTE FUNCTION fn_price_delivery();
CREATE OR REPLACE PROCEDURE pr_receive_delivery(p_farmer_id INT,p_grade CHAR(1),p_weight NUMERIC,p_date DATE) LANGUAGE plpgsql AS $$
BEGIN IF NOT EXISTS(SELECT 1 FROM farmers WHERE farmer_id=p_farmer_id) THEN RAISE EXCEPTION 'Unknown farmer'; END IF; IF p_weight IS NULL OR p_weight<=0 OR p_date IS NULL THEN RAISE EXCEPTION 'Positive weight and delivery date required'; END IF; PERFORM fn_maize_rate(p_grade); INSERT INTO deliveries(farmer_id,grade,weight_kg,delivered_on,is_paid) VALUES(p_farmer_id,upper(p_grade),p_weight,p_date,FALSE); END $$;
CALL pr_receive_delivery(1,'A',100,CURRENT_DATE-2); CALL pr_receive_delivery(2,'B',150,CURRENT_DATE-2); CALL pr_receive_delivery(3,'C',200,CURRENT_DATE-2); CALL pr_receive_delivery(1,'B',75,CURRENT_DATE-1); CALL pr_receive_delivery(2,'A',80,CURRENT_DATE-1); CALL pr_receive_delivery(3,'C',120,CURRENT_DATE-1);
UPDATE deliveries SET is_paid=TRUE WHERE delivery_id IN(2,4);
CREATE OR REPLACE VIEW v_farmer_amount_due AS SELECT f.farmer_number,f.full_name,COALESCE(sum(d.total_value) FILTER(WHERE d.is_paid=FALSE),0) AS amount_due FROM farmers f LEFT JOIN deliveries d USING(farmer_id) GROUP BY f.farmer_id;
CREATE INDEX IF NOT EXISTS ix_deliveries_farmer_date ON deliveries(farmer_id,delivered_on);
EXPLAIN SELECT * FROM deliveries WHERE farmer_id=1 AND delivered_on BETWEEN CURRENT_DATE-30 AND CURRENT_DATE;
CREATE OR REPLACE PROCEDURE pr_refresh_purchases(p_day DATE) LANGUAGE plpgsql AS $$
BEGIN IF p_day IS NULL THEN RAISE EXCEPTION 'Date required'; END IF; INSERT INTO daily_purchases SELECT p_day,COALESCE(sum(weight_kg),0),COALESCE(sum(total_value),0) FROM deliveries WHERE delivered_on=p_day ON CONFLICT(purchase_date) DO UPDATE SET total_weight=EXCLUDED.total_weight,total_value=EXCLUDED.total_value; END $$;
CALL pr_refresh_purchases(CURRENT_DATE-1);
-- Schedule daily at 01:30 for previous day: CALL maize_q9.pr_refresh_purchases(CURRENT_DATE-1).
SELECT * FROM v_farmer_amount_due; SELECT * FROM daily_purchases;